import { useCallback, useEffect, useMemo, useState } from "react";
import { CheckCircle2, ExternalLink, RefreshCw, ShieldAlert } from "lucide-react";
import { useSearchParams } from "react-router-dom";
import { PageHeader } from "../../shared/ui/PageHeader";
import type { AdminArea, AssetAuthority, ExceptionItem, Fulfillment, LineageDiagnostics, Publication, PurchaseIntent, RoleAssignment, SalesDecision, SalesSession } from "./types";
import "./commercial-administration.css";
import "./commercial-administration-states.css";

const areas: [AdminArea, string][] = [["overview", "Overview"], ["customers", "Customers"], ["catalog", "Catalog"], ["sales", "Sales"], ["delivery", "Delivery"], ["diagnostics", "Diagnostics"]];
const labels = (value?: string | null) => String(value || "Unknown").replaceAll("_", " ").toLowerCase().replace(/\b\w/g, (letter) => letter.toUpperCase());
const when = (value?: string | null) => value ? new Date(value).toLocaleString() : "Time unavailable";
const idList = (values: { asset_id: number }[]) => values.map((value) => value.asset_id).join(", ") || "None";

class AuthorityError extends Error { constructor(message: string, readonly status: number) { super(message); } }
async function read<T>(url: string): Promise<T> { const response = await fetch(url, { cache: "no-store" }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new AuthorityError(body.detail || "Authoritative data is unavailable.", response.status); return body as T; }
async function command(url: string, body: Record<string, unknown>) { const response = await fetch(url, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new AuthorityError(payload.detail || "The canonical authority rejected this command.", response.status); return payload; }

type AuthorityData = {
  customers: Record<string, unknown>[]; assets: Record<string, unknown>[];
  products: Record<string, unknown>[]; offerings: Record<string, unknown>[];
  sessions: SalesSession[]; publications: Publication[]; intents: PurchaseIntent[];
  decisions: SalesDecision[]; learning: Record<string, unknown>;
  assetAuthorities: AssetAuthority[]; fulfillments: Fulfillment[];
};
const emptyData: AuthorityData = { customers: [], assets: [], products: [], offerings: [], sessions: [], publications: [], intents: [], decisions: [], learning: {}, assetAuthorities: [], fulfillments: [] };

export function CommercialAdministrationPage() {
  const [params, setParams] = useSearchParams();
  const requested = params.get("area") as AdminArea | null;
  const area = areas.some(([value]) => value === requested) ? requested! : "overview";
  const [data, setData] = useState<AuthorityData>(emptyData);
  const [loading, setLoading] = useState(true); const [fatal, setFatal] = useState<AuthorityError | null>(null); const [partial, setPartial] = useState<string[]>([]);

  const refresh = useCallback(async () => {
    setLoading(true); setFatal(null);
    const sources = [
      ["customers", "/api/v1/customers?page_size=100"], ["assets", "/api/v1/business-assets?page_size=100"],
      ["products", "/api/v1/products?page_size=100"], ["offerings", "/api/v1/commercial-offerings?page_size=100"],
      ["sessions", "/api/v1/sales-sessions?limit=500"], ["publications", "/api/v1/commercial-publications"],
      ["intents", "/api/v1/commercial-administration/purchase-intents?page_size=100"], ["decisions", "/api/v1/sales/decisions?page_size=100"],
      ["learning", "/api/v1/sales/learning"],
    ] as const;
    const results = await Promise.allSettled(sources.map(([, url]) => read<Record<string, unknown>>(url)));
    const next: AuthorityData = { ...emptyData }; const unavailable: string[] = []; let firstError: AuthorityError | null = null;
    results.forEach((result, index) => { const name = sources[index]![0]; if (result.status === "rejected") { unavailable.push(labels(name)); if (!firstError && result.reason instanceof AuthorityError) firstError = result.reason; return; } if (name === "learning") next.learning = result.value; else (next[name] as unknown[]) = (result.value.items as unknown[]) || []; });
    const assetResults = await Promise.allSettled(next.assets.filter((item) => item.itemKind !== "photoshoot" && Number(item.asset_id) > 0).map(async (item) => { const assetId = Number(item.asset_id); const [roles, lineage] = await Promise.all([read<{ items: RoleAssignment[] }>(`/api/v1/commercial-roles/assets/${assetId}`), read<LineageDiagnostics>(`/api/v1/asset-lineage/assets/${assetId}`)]); if (!Array.isArray(lineage.completeness_issues)) throw new AuthorityError("Lineage projection unavailable.", 503); return { assetId, roles: roles.items, lineage }; }));
    next.assetAuthorities = assetResults.flatMap((result) => result.status === "fulfilled" ? [result.value] : []); if (assetResults.some((result) => result.status === "rejected")) unavailable.push("Role or Lineage summaries");
    const fulfillmentResults = await Promise.allSettled(next.offerings.map((item) => read<Fulfillment>(`/api/v1/commercial-fulfillments/${item.offeringId}`)));
    next.fulfillments = fulfillmentResults.flatMap((result) => result.status === "fulfilled" ? [result.value] : []); if (fulfillmentResults.some((result) => result.status === "rejected")) unavailable.push("Fulfillment details");
    setData(next); setPartial([...new Set(unavailable)]); if (results.every((result) => result.status === "rejected")) setFatal(firstError || new AuthorityError("Commercial authorities are unavailable.", 503)); setLoading(false);
  }, []);
  useEffect(() => { void refresh(); }, [refresh]);
  const exceptions = useMemo(() => buildExceptions(data), [data]);
  const navigate = (next: AdminArea, values: Record<string, string> = {}) => setParams(next === "overview" && !Object.keys(values).length ? {} : { area: next, ...values });

  return <section className="commercial-admin"><PageHeader title="Commercial Administration" description="Creator-scoped operations across the canonical commercial platform." />
    <div className="commercial-admin__authority"><ShieldAlert size={18} /><span><strong>Composition only.</strong> State and actions remain owned by their named canonical authority.</span><button aria-label="Refresh authoritative state" disabled={loading} onClick={() => void refresh()}><RefreshCw size={15} />Refresh</button></div>
    <nav aria-label="Commercial Administration areas" className="commercial-admin__tabs">{areas.map(([value, title]) => <button aria-selected={area === value} key={value} onClick={() => navigate(value)} role="tab">{title}</button>)}</nav>
    {loading && <OperatorState kind="loading">Loading authoritative commercial state…</OperatorState>}
    {!loading && fatal && <ErrorState error={fatal} />}
    {!loading && !fatal && partial.length > 0 && <OperatorState kind="dependency">Partial data: {partial.join(", ")} unavailable. Missing evidence remains unknown.</OperatorState>}
    {!loading && !fatal && area === "overview" && <Overview exceptions={exceptions} data={data} navigate={navigate} />}
    {!loading && !fatal && area === "customers" && <Customers data={data} selectedId={params.get("customer")} navigate={navigate} />}
    {!loading && !fatal && area === "catalog" && <Catalog data={data} selectedAsset={params.get("asset")} navigate={navigate} refresh={refresh} />}
    {!loading && !fatal && area === "sales" && <><SessionStarter refresh={refresh} /><PurchaseIntentInspector intentId={params.get("intent")} data={data} navigate={navigate} /><Sales data={data} selectedSession={params.get("session")} navigate={navigate} refresh={refresh} /></>}
    {!loading && !fatal && area === "delivery" && <Delivery data={data} refresh={refresh} />}
    {!loading && !fatal && area === "diagnostics" && <><DecisionInspector decisionId={params.get("decision")} data={data} navigate={navigate} /><Diagnostics data={data} exceptions={exceptions} navigate={navigate} /></>}
  </section>;
}

function Overview({ exceptions, data, navigate }: { exceptions: ExceptionItem[]; data: AuthorityData; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  return <div className="commercial-admin__area"><section className="commercial-admin__metrics"><Metric label="Actionable Exceptions" value={exceptions.length} /><Metric label="Pending Role Approvals" value={data.assetAuthorities.flatMap((item) => item.roles).filter((role) => role.state === "SUGGESTED").length} /><Metric label="Active Sessions" value={data.sessions.filter((item) => item.state === "ACTIVE").length} /><Metric label="Failed Publications" value={data.publications.filter((item) => item.status === "FAILED").length} /></section><Heading title="Needs attention" description="Canonical evidence composed by authority; local filtering never changes commercial state." />{exceptions.length ? <ExceptionList items={exceptions} navigate={navigate} /> : <OperatorState kind="empty">No actionable exceptions were reported by available authorities.</OperatorState>}</div>;
}

function Customers({ data, selectedId, navigate }: { data: AuthorityData; selectedId: string | null; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  const [detail, setDetail] = useState<Record<string, unknown> | null>(null); const [state, setState] = useState<AuthorityError | null>(null);
  useEffect(() => { if (!selectedId) { setDetail(null); return; } read<Record<string, unknown>>(`/api/v1/customers/${encodeURIComponent(selectedId)}`).then(setDetail).catch((reason) => setState(reason)); }, [selectedId]);
  const relatedSessions = data.sessions.filter((item) => selectedId?.endsWith(`:${item.fanvueUserId}`)); const relatedIntents = data.intents.filter((item) => item.fanvueAccountId && selectedId?.startsWith(`${item.fanvueAccountId}:`)); const relatedDecisions = data.decisions.filter((item) => item.customerId === selectedId);
  let content: React.ReactNode;
  if (!selectedId) content = <div className="commercial-admin__grid">{data.customers.map((item) => { const id = String(item.customerId); return <button className="commercial-admin__card commercial-admin__select-card" key={id} onClick={() => navigate("customers", { customer: id })}><small>Customer authority</small><h3>{String(item.displayName || id)}</h3><code>{id}</code><p>{labels(String(item.relationshipStage))} · {Number(item.purchaseCount || 0)} purchases</p></button>; })}</div>;
  else if (state) content = <><button className="commercial-admin__back" onClick={() => navigate("customers")}>← All customers</button><ErrorState error={state} /></>;
  else if (!detail) content = <OperatorState kind="loading">Loading canonical customer journey…</OperatorState>;
  else { const evidence = JSON.stringify([detail, relatedSessions, relatedIntents, relatedDecisions]); const offerings = data.offerings.filter((item) => evidence.includes(String(item.offeringId))); const products = data.products.filter((item) => evidence.includes(String(item.productId))); const assets = data.assets.filter((item) => evidence.includes(String(item.asset_id))); const publications = data.publications.filter((item) => evidence.includes(item.publicationId) || offerings.some((offering) => String(offering.offeringId) === item.commercialOfferingId)); const fulfillment = data.fulfillments.filter((item) => offerings.some((offering) => String(offering.offeringId) === item.offeringId)); content = <><button className="commercial-admin__back" onClick={() => navigate("customers")}>← All customers</button><div className="commercial-admin__split"><RecordCard authority="Customer" title={String(detail.displayName || selectedId)} id={selectedId} value={detail} /><section className="commercial-admin__card"><small>Cross-domain journey</small><h3>Related canonical records</h3><Relation label="Sales Sessions" values={relatedSessions.map((item) => [item.salesSessionId, () => navigate("sales", { session: item.salesSessionId })])} /><Relation label="Purchase Intents" values={relatedIntents.map((item) => [item.purchaseIntentId, () => navigate("sales", { intent: item.purchaseIntentId })])} /><Relation label="Commercial Decisions" values={relatedDecisions.map((item) => [item.decisionId, () => navigate("diagnostics", { decision: item.decisionId })])} /><StructuredFields title="Ownership Intelligence, coverage, remaining value, and Lineage" value={detail.commerceAndOwnership} /></section></div><div className="commercial-admin__grid"><RecordCard authority="Offerings and Bundle coverage" title={`${offerings.length} related records`} id={null} value={offerings} /><RecordCard authority="Products and Assets" title={`${products.length} Products · ${assets.length} Assets`} id={null} value={{ products, assets }} /><RecordCard authority="Publication and Fulfillment" title={`${publications.length} Publications · ${fulfillment.length} fulfillment records`} id={null} value={{ publications, fulfillment }} /><RecordCard authority="Commercial Intelligence" title={`${relatedDecisions.length} historical decisions`} id={null} value={relatedDecisions} /></div></>; }
  return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Customers", selectedId || "All customers"]} /><Heading title="Customer journey" description="Ownership is supplied by canonical Ownership Intelligence; no administrative ownership joins are created." />{content}{Boolean(detail?.customerIntelligenceProfile) && <CustomerIntelligenceEvidence profile={detail!.customerIntelligenceProfile as Record<string, unknown>} navigate={navigate} />}</div>;
}

function CustomerIntelligenceEvidence({ profile, navigate }: { profile: Record<string, unknown>; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  const facts = (profile.facts as Record<string, unknown>[] | undefined) || [];
  const destination = (fact: Record<string, unknown>): [AdminArea, Record<string, string>] | null => { const authority = String(fact.authority || ""); const id = String(fact.record_id || ""); if (authority === "Sales Sessions") return ["sales", { session: id }]; if (authority === "Purchase Intents") return ["sales", { intent: id }]; if (authority === "Recommendation and Outcome History") return ["diagnostics", { decision: id }]; if (["Publication", "Fulfillment", "Delivery"].includes(authority)) return ["delivery", {}]; return null; };
  return <section className="commercial-admin__card"><small>Customer Intelligence · read-only evidence authority</small><h3>Canonical Customer Intelligence profile</h3><Definition values={{ State: labels(String(profile.profile_state)), "Identity confidence": `${Math.round(Number(profile.identity_confidence || 0) * 100)}%`, Conflicts: String((profile.conflicts as unknown[] | undefined)?.length || 0), Insufficiencies: String((profile.insufficiencies as unknown[] | undefined)?.length || 0), "Evidence count": String(facts.length || (profile.provenance as Record<string, unknown> | undefined)?.included_evidence_count || 0), "Calculation method": String((profile.calculation_metadata as Record<string, unknown> | undefined)?.method_version || "Unavailable"), "Calculated at": when(String((profile.calculation_metadata as Record<string, unknown> | undefined)?.calculated_at || "")) }} /><StructuredFields title="Independent section states" value={{ states: profile.section_states, reasons: profile.section_state_reasons }} /><StructuredFields title="Source availability" value={(profile.provenance as Record<string, unknown> | undefined)?.source_failures || { status: "Available where evidence counts are non-zero" }} /><StructuredFields title="Conflicts and insufficiencies" value={{ conflicts: profile.conflicts, insufficiencies: profile.insufficiencies }} /><StructuredFields title="Calculation metadata and profile provenance" value={{ calculation_metadata: profile.calculation_metadata, provenance: profile.provenance }} /><StructuredFields title="Per-output provenance" value={{ spending_profile: profile.spending_profile, session_profile: profile.session_profile, bundle_behavior: profile.bundle_behavior, video_conversion: profile.video_conversion, engagement_profile: profile.engagement_profile, recommendation_history: profile.recommendation_history, purchase_preferences: profile.purchase_preferences, media_preferences: profile.media_preferences, classifications: profile.classifications, opportunities: profile.opportunities, risks: profile.risks }} /><div><h4>Source navigation</h4>{facts.length ? <ul>{facts.map((fact, index) => { const route = destination(fact); return <li key={`${String(fact.authority)}-${String(fact.record_id)}-${index}`}><strong>{String(fact.authority || "Unknown authority")}</strong> · <code>{String(fact.record_id || "Unidentified record")}</code> {route ? <button onClick={() => navigate(route[0], route[1])}>Open canonical source</button> : <small>Non-navigable source</small>}</li>; })}</ul> : <p>No source references are available.</p>}</div><StructuredFields title="Historical recommendation and outcome evidence" value={profile.recommendation_history} /></section>;
}

function Catalog({ data, selectedAsset, navigate, refresh }: { data: AuthorityData; selectedAsset: string | null; navigate: (area: AdminArea, values?: Record<string, string>) => void; refresh: () => Promise<void> }) {
  const [query, setQuery] = useState(""); const [roles, setRoles] = useState<RoleAssignment[]>([]); const [history, setHistory] = useState<Record<string, unknown>[]>([]); const [lineage, setLineage] = useState<LineageDiagnostics | null>(null); const [assetDetail, setAssetDetail] = useState<Record<string, unknown> | null>(null); const [vocabulary, setVocabulary] = useState<string[]>([]); const [role, setRole] = useState(""); const [notice, setNotice] = useState<{ kind: "stale" | "unauthorized" | "unsupported" | "failed"; text: string } | null>(null);
  const inspect = useCallback(async (id: number, suggest = false) => { try { if (suggest) await command(`/api/v1/commercial-roles/assets/${id}/suggestions`, {}); const [roleData, roleHistory, lineageData, vocabularyData, detailData] = await Promise.all([read<{ items: RoleAssignment[] }>(`/api/v1/commercial-roles/assets/${id}`), read<{ items: Record<string, unknown>[] }>(`/api/v1/commercial-roles/assets/${id}/history`), read<LineageDiagnostics>(`/api/v1/asset-lineage/assets/${id}`), read<{ roles: string[] }>("/api/v1/commercial-roles/vocabulary"), read<Record<string, unknown>>(`/api/v1/business-assets/${id}`)]); setRoles(roleData.items); setHistory(roleHistory.items); setLineage(lineageData); setVocabulary(vocabularyData.roles); setRole(vocabularyData.roles[0] || ""); setAssetDetail(detailData); setNotice(null); } catch (reason) { setNotice(classifyCommandError(reason)); } }, []);
  useEffect(() => { if (selectedAsset) void inspect(Number(selectedAsset)); }, [selectedAsset, inspect]);
  const roleAction = async (action: string, selectedRole: string) => { if (!confirm(`${labels(action)} ${selectedRole}? The Commercial Role authority will validate current state and record history.`)) return; try { await command(`/api/v1/commercial-roles/assets/${selectedAsset}/${action === "assign" ? "assignments" : action}`, { role: selectedRole, reason: "Commercial Administration operator action" }); await inspect(Number(selectedAsset)); await refresh(); } catch (reason) { setNotice(classifyCommandError(reason)); } };
  const matches = (item: Record<string, unknown>) => JSON.stringify(item).toLowerCase().includes(query.toLowerCase()); const bundles = data.offerings.filter((item) => ["PHOTOSET", "STORY_SET", "MIXED_SET"].includes(String(item.offeringType)));
  const details = <><button className="commercial-admin__back" onClick={() => navigate("catalog")}>← All catalog records</button>{notice && <OperatorState kind={notice.kind}>{notice.text}</OperatorState>}{lineage && <div className="commercial-admin__split"><section className="commercial-admin__card"><small>Asset Lineage authority</small><h3>Asset #{lineage.asset_id} · {lineage.classification}</h3><Definition values={{ Integrity: lineage.integrity_status, Ambiguity: lineage.ambiguous ? "Ambiguous" : "Unambiguous", Roots: idList(lineage.roots), Parents: idList(lineage.parents), Children: idList(lineage.children), Siblings: idList(lineage.siblings), Ancestors: idList(lineage.ancestors), Descendants: idList(lineage.descendants), Family: lineage.family_asset_ids.join(", "), Provenance: lineage.provenance_complete ? "Complete" : "Incomplete", Issues: lineage.completeness_issues.join(", ") || "None" }} /><StructuredFields title="Photoshoot context" value={lineage.photoshoot_contexts} /><StructuredFields title="Derivation relationships and provenance" value={lineage.relationships} /></section><section className="commercial-admin__card"><small>Commercial Role authority</small><h3>Assignments and suggestions</h3>{roles.map((item) => <article className="commercial-admin__role" key={item.assignmentId}><div><strong>{labels(item.role)}</strong><Status good={item.state === "APPROVED"}>{labels(item.state)}</Status></div><Definition values={{ Origin: labels(item.origin), Confidence: item.suggestionConfidence == null ? "Not applicable" : `${Math.round(item.suggestionConfidence * 100)}%`, Rationale: item.rationale || "None" }} /><StructuredFields title="Suggestion evidence" value={item.evidence} /><div>{item.state === "SUGGESTED" && <><button onClick={() => void roleAction("approve", item.role)}>Approve</button><button onClick={() => void roleAction("reject", item.role)}>Reject</button></>}{item.state === "APPROVED" && <button onClick={() => void roleAction("deactivate", item.role)}>Deactivate</button>}{item.state === "INACTIVE" && <><button onClick={() => void roleAction("reactivate", item.role)}>Reactivate</button><button onClick={() => void roleAction("retire", item.role)}>Retire</button></>}</div></article>)}<div className="commercial-admin__inline"><select aria-label="Commercial Role" onChange={(event) => setRole(event.target.value)} value={role}>{vocabulary.map((item) => <option key={item}>{item}</option>)}</select><button onClick={() => void roleAction("assign", role)}>Assign Role</button><button onClick={() => void inspect(Number(selectedAsset), true)}>Generate Suggestions</button></div><StructuredFields title={`Append-only role history (${history.length})`} value={history} /></section></div>}{assetDetail && <RecordCard authority="Asset commerce" title={`Asset #${selectedAsset}`} id={selectedAsset} value={assetDetail} />}</>;
  const listing = <><RoleQueues authorities={data.assetAuthorities} navigate={navigate} /><CatalogGroup title="Assets" items={data.assets.filter(matches)} idKey="asset_id" onSelect={(id) => navigate("catalog", { asset: id })} /><CatalogGroup title="Offerings" items={data.offerings.filter(matches)} idKey="offeringId" /><CatalogGroup title="Products" items={data.products.filter(matches)} idKey="productId" /><BundleOperations bundles={bundles.filter(matches)} data={data} navigate={navigate} /></>;
  return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Catalog", selectedAsset ? `Asset ${selectedAsset}` : "All records"]} /><Heading title="Catalog operations" description="Assets, Roles, Lineage, Offerings, Products, and Bundles retain separate authority." /><label className="commercial-admin__search">Search canonical catalog<input aria-label="Search canonical catalog" onChange={(event) => setQuery(event.target.value)} value={query} /></label>{selectedAsset ? details : listing}</div>;
}

function RoleQueues({ authorities, navigate }: { authorities: AssetAuthority[]; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  const [role, setRole] = useState("ALL"); const [lifecycle, setLifecycle] = useState("ALL"); const [queue, setQueue] = useState("ALL"); const [confidence, setConfidence] = useState("0");
  const vocabulary = [...new Set(authorities.flatMap((item) => item.roles.map((assignment) => assignment.role)))];
  const allRows: { authority: AssetAuthority; assignment: RoleAssignment | null }[] = authorities.reduce<{ authority: AssetAuthority; assignment: RoleAssignment | null }[]>((values, authority) => values.concat(authority.roles.length ? authority.roles.map((assignment) => ({ authority, assignment })) : [{ authority, assignment: null }]), []); const rows = allRows.filter(({ assignment }) => (role === "ALL" || assignment?.role === role) && (lifecycle === "ALL" || assignment?.state === lifecycle) && (queue === "ALL" || (queue === "PENDING" && assignment?.state === "SUGGESTED") || (queue === "MISSING" && !assignment)) && Number(assignment?.suggestionConfidence || 0) >= Number(confidence));
  return <section><Heading title="Commercial Role queues" description="Creator-scoped assignments, pending suggestions, and Assets missing an effective role." /><div className="commercial-admin__filters"><select aria-label="Role filter" value={role} onChange={(event) => setRole(event.target.value)}><option>ALL</option>{vocabulary.map((item) => <option key={item}>{item}</option>)}</select><select aria-label="Role lifecycle filter" value={lifecycle} onChange={(event) => setLifecycle(event.target.value)}>{["ALL", "SUGGESTED", "APPROVED", "INACTIVE", "REJECTED", "RETIRED"].map((item) => <option key={item}>{item}</option>)}</select><select aria-label="Role queue filter" value={queue} onChange={(event) => setQueue(event.target.value)}><option>ALL</option><option value="PENDING">PENDING</option><option value="MISSING">MISSING ROLE</option></select><select aria-label="Minimum confidence" value={confidence} onChange={(event) => setConfidence(event.target.value)}><option value="0">Any confidence</option><option value="0.5">50%+</option><option value="0.8">80%+</option></select></div><div className="commercial-admin__table">{rows.map(({ authority, assignment }) => <button className="commercial-admin__row" key={`${authority.assetId}-${assignment?.assignmentId || "missing"}`} onClick={() => navigate("catalog", { asset: String(authority.assetId) })}><span><small>Asset</small><strong>#{authority.assetId}</strong></span><span><small>Role</small><strong>{assignment ? labels(assignment.role) : "Missing effective role"}</strong></span><span><small>Lifecycle</small><strong>{labels(assignment?.state || "MISSING")}</strong></span><span><small>Confidence</small><strong>{assignment?.suggestionConfidence == null ? "Not supplied" : `${Math.round(assignment.suggestionConfidence * 100)}%`}</strong></span></button>)}</div>{!rows.length && <OperatorState kind="empty">No Commercial Role records match these filters.</OperatorState>}</section>;
}

function BundleOperations({ bundles, data, navigate }: { bundles: Record<string, unknown>[]; data: AuthorityData; navigate: (area: AdminArea, values?: Record<string, string>) => void }) { return <section><Heading title="Bundles" description={`${bundles.length} canonical Commercial Offerings with ordered composition and delivery readiness.`} /><div className="commercial-admin__grid">{bundles.map((bundle) => { const id = String(bundle.offeringId); const fulfillment = data.fulfillments.find((item) => item.offeringId === id); const ordered = fulfillment?.orderedAssetIds || (bundle.orderedAssetIds as number[] | undefined) || []; const authorities = data.assetAuthorities.filter((item) => ordered.includes(item.assetId)); const originals = authorities.filter((item) => item.lineage?.classification === "ORIGINAL").map((item) => item.assetId); const derivatives = authorities.filter((item) => item.lineage?.classification !== "ORIGINAL").map((item) => item.assetId); return <article className="commercial-admin__card" key={id}><small>Commercial Offering authority</small><h3>{String(bundle.title || id)}</h3><Definition values={{ Lifecycle: labels(String(bundle.status)), "Ordered composition": ordered.join(", ") || "Not supplied", Originals: originals.join(", ") || "None identified", Derivatives: derivatives.join(", ") || "None identified", "Publication readiness": fulfillment?.publicationStatus || "Unknown", "Fulfillment readiness": fulfillment?.fulfillable ? "Ready" : fulfillment?.ineligibilityReason || "Blocked or unknown", "Media Link": fulfillment?.providerResourceId || "Not retrieved", "Remaining value / ownership": String(bundle.remainingValue || bundle.ownershipCoverage || "Canonical evidence not supplied") }} /><StructuredFields title="Photoshoot and Lineage context" value={authorities.map((item) => item.lineage)} /><Relation label="Assets" values={ordered.map((assetId) => [String(assetId), () => navigate("catalog", { asset: String(assetId) })])} /></article>; })}</div>{!bundles.length && <OperatorState kind="empty">No matching bundles.</OperatorState>}</section>; }

function SessionStarter({ refresh }: { refresh: () => Promise<void> }) {
  const [open, setOpen] = useState(false); const [account, setAccount] = useState(""); const [customer, setCustomer] = useState(""); const [foundationType, setFoundationType] = useState<"PHOTOSHOOT" | "CONVERSATION">("PHOTOSHOOT"); const [foundation, setFoundation] = useState(""); const [conversation, setConversation] = useState(""); const [notice, setNotice] = useState<{ kind: "stale" | "unauthorized" | "unsupported" | "failed"; text: string } | null>(null);
  const start = async () => { if (!confirm(`Start a Sales Session for Fanvue customer ${customer}?`)) return; try { await command("/api/v1/sales-sessions", { fanvueAccountId: Number(account), fanvueUserId: Number(customer), commercialFoundationType: foundationType, ...(foundationType === "PHOTOSHOOT" ? { commercialFoundationReference: foundation } : { conversationThreadId: Number(conversation) }), actorType: "OPERATOR" }); await refresh(); setOpen(false); setNotice(null); } catch (reason) { setNotice(classifyCommandError(reason)); } };
  const foundationReady = foundationType === "PHOTOSHOOT" ? Boolean(foundation.trim()) : Number(conversation) > 0;
  return <section className="commercial-admin__area commercial-admin__starter"><button onClick={() => setOpen((value) => !value)}>{open ? "Cancel Session start" : "Start Session"}</button>{notice && <OperatorState kind={notice.kind}>{notice.text}</OperatorState>}{open && <div className="commercial-admin__filters"><input aria-label="Fanvue Account ID" inputMode="numeric" onChange={(event) => setAccount(event.target.value)} placeholder="Fanvue account ID" value={account} /><input aria-label="Fanvue Customer ID" inputMode="numeric" onChange={(event) => setCustomer(event.target.value)} placeholder="Fanvue customer ID" value={customer} /><select aria-label="Foundation Type" value={foundationType} onChange={(event) => setFoundationType(event.target.value as "PHOTOSHOOT" | "CONVERSATION")}><option value="PHOTOSHOOT">Photoshoot</option><option value="CONVERSATION">Conversation</option></select>{foundationType === "PHOTOSHOOT" ? <input aria-label="Commercial Foundation Reference" onChange={(event) => setFoundation(event.target.value)} placeholder="Canonical Photoshoot reference" value={foundation} /> : <input aria-label="Conversation Thread ID" inputMode="numeric" onChange={(event) => setConversation(event.target.value)} placeholder="Canonical conversation thread ID" value={conversation} />}<button disabled={!Number(account) || !Number(customer) || !foundationReady} onClick={() => void start()}>Confirm Session start</button></div>}</section>;
}

function PurchaseIntentInspector({ intentId, data, navigate }: { intentId: string | null; data: AuthorityData; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  if (!intentId) return null; const intent = data.intents.find((item) => item.purchaseIntentId === intentId); if (!intent) return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Sales", "Purchase Intent", intentId]} /><OperatorState kind="insufficient">The creator-scoped Purchase Intent projection did not return this canonical identifier.</OperatorState></div>;
  const publication = data.publications.find((item) => item.publicationId === intent.commercialPublicationId); const fulfillment = data.fulfillments.find((item) => item.publicationId === intent.commercialPublicationId || item.offeringId === intent.commercialOfferingId); const decisions = data.decisions.filter((item) => JSON.stringify(item).includes(intentId) || JSON.stringify(item).includes(intent.commercialOfferingId));
  return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Sales", "Purchase Intent", intentId]} /><button className="commercial-admin__back" onClick={() => navigate("sales")}>← Session queues</button><Heading title="Purchase Intent inspection" description="Read-only evidence from the canonical Purchase Intent, Publication, Fulfillment, and Intelligence authorities." /><div className="commercial-admin__grid"><RecordCard authority="Purchase Intent" title={intent.purchaseIntentId} id={intent.purchaseIntentId} value={intent} /><RecordCard authority="Publication" title={publication?.publicationId || "Unavailable"} id={publication?.publicationId || null} value={publication || { insufficiency: "No matching canonical Publication" }} /><RecordCard authority="Fulfillment and Delivery" title={fulfillment?.offeringId || intent.commercialOfferingId} id={fulfillment?.offeringId || null} value={fulfillment || { insufficiency: "No matching canonical fulfillment projection" }} /></div><Relation label="Historical Commercial Intelligence" values={decisions.map((item) => [item.decisionId, () => navigate("diagnostics", { decision: item.decisionId, intent: intentId })])} /></div>;
}

function DecisionInspector({ decisionId, data, navigate }: { decisionId: string | null; data: AuthorityData; navigate: (area: AdminArea, values?: Record<string, string>) => void }) {
  const [detail, setDetail] = useState<Record<string, unknown> | null>(null); const [error, setError] = useState<AuthorityError | null>(null);
  useEffect(() => { if (!decisionId) { setDetail(null); setError(null); return; } read<Record<string, unknown>>(`/api/v1/sales/decisions/${encodeURIComponent(decisionId)}`).then(setDetail).catch((reason) => setError(reason)); }, [decisionId]);
  if (!decisionId) return null; if (error) return <div className="commercial-admin__area"><ErrorState error={error} /></div>; if (!detail) return <div className="commercial-admin__area"><OperatorState kind="loading">Loading historical Commercial Intelligence…</OperatorState></div>;
  const decision = data.decisions.find((item) => item.decisionId === decisionId); const session = data.sessions.find((item) => JSON.stringify(detail).includes(item.salesSessionId)); const intent = data.intents.find((item) => JSON.stringify(detail).includes(item.purchaseIntentId));
  return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Diagnostics", "Commercial Intelligence", decisionId]} /><button className="commercial-admin__back" onClick={() => navigate("diagnostics")}>← Diagnostics</button><Heading title="Commercial Intelligence inspector" description="Historical persisted reasoning only. This workspace never reruns a decision." /><RecordCard authority="Commercial Intelligence" title={decisionId} id={decisionId} value={detail} /><div className="commercial-admin__grid"><StructuredPanel title="Strategy, reasoning, ranking, rejection, and suppression" value={{ classificationAndRouting: detail.classificationAndRouting, sellDecision: detail.sellDecision, recommendation: detail.recommendation, outcomeAndLearning: detail.outcomeAndLearning }} /><StructuredPanel title="Ownership, Customer Sales Brain, and delivery" value={{ customerContext: detail.customerContext, delivery: detail.delivery, conversation: detail.conversation, warnings: detail.warnings, insufficiency: detail.partialSections }} /></div><Relation label="Canonical context" values={[[String(decision?.customerId || "Customer"), () => decision?.customerId && navigate("customers", { customer: decision.customerId })], ...(session ? [[session.salesSessionId, () => navigate("sales", { session: session.salesSessionId })] as [string, () => void]] : []), ...(intent ? [[intent.purchaseIntentId, () => navigate("sales", { intent: intent.purchaseIntentId })] as [string, () => void]] : [])]} /></div>;
}

function StructuredPanel({ title, value }: { title: string; value: Record<string, unknown> }) { return <section className="commercial-admin__card"><h3>{title}</h3>{Object.entries(value).map(([key, item]) => <StructuredFields key={key} title={labels(key)} value={item} />)}</section>; }

function Sales({ data, selectedSession, navigate, refresh }: { data: AuthorityData; selectedSession: string | null; navigate: (area: AdminArea, values?: Record<string, string>) => void; refresh: () => Promise<void> }) {
  const [query, setQuery] = useState(""); const [stateFilter, setStateFilter] = useState("ALL"); const [progression, setProgression] = useState(""); const [customer, setCustomer] = useState(""); const [photoshoot, setPhotoshoot] = useState(""); const [activity, setActivity] = useState(""); const [expiration, setExpiration] = useState(""); const [outcome, setOutcome] = useState(""); const [detail, setDetail] = useState<Record<string, unknown> | null>(null); const [notice, setNotice] = useState<{ kind: "stale" | "unauthorized" | "unsupported" | "failed"; text: string } | null>(null); const selected = data.sessions.find((item) => item.salesSessionId === selectedSession);
  useEffect(() => { if (!selectedSession) { setDetail(null); return; } Promise.all([read<Record<string, unknown>>(`/api/v1/sales-sessions/${selectedSession}/history`), read<Record<string, unknown>>(`/api/v1/sales-sessions/${selectedSession}/commercial-context`)]).then(([history, context]) => setDetail({ history, context })).catch((reason) => setNotice(classifyCommandError(reason))); }, [selectedSession]);
  const act = async (action: string, body: Record<string, unknown> = {}) => { if (!selected || !confirm(`${labels(action)} Sales Session ${selected.salesSessionId}? Current state will be validated by the Sales Session authority.`)) return; try { await command(`/api/v1/sales-sessions/${selected.salesSessionId}/${action}`, { reason: "Commercial Administration operator action", ...body }); await refresh(); setNotice(null); } catch (reason) { setNotice(classifyCommandError(reason)); } };
  const visible = data.sessions.filter((item) => { const text = JSON.stringify(item).toLowerCase(); const updated = new Date(item.lastActivityAt || 0).getTime(); const before = activity ? updated <= new Date(activity).getTime() : true; const expires = String((item as unknown as Record<string, unknown>).expiresAt || ""); return (stateFilter === "ALL" || item.state === stateFilter) && (!progression || item.progressionStage === progression) && (!customer || String(item.fanvueUserId).includes(customer)) && (!photoshoot || text.includes(photoshoot.toLowerCase())) && before && (!expiration || expires.startsWith(expiration)) && (!outcome || String(item.outcome || "").toUpperCase() === outcome.toUpperCase()) && text.includes(query.toLowerCase()); }); const intents = data.intents.filter((item) => !selected || String((detail?.context as Record<string, unknown>)?.customerId || "").endsWith(String(item.fanvueAccountId)) || JSON.stringify(detail || {}).includes(item.purchaseIntentId));
  return <div className="commercial-admin__area"><Breadcrumb values={["Commercial Administration", "Sales", selectedSession || "Session queues"]} /><Heading title="Sales operations" description="Sessions, Purchase Intents, recorded Intelligence, outcomes, Publication, and Delivery remain independently authoritative." /><div className="commercial-admin__filters"><input aria-label="Filter Sales Sessions" onChange={(event) => setQuery(event.target.value)} placeholder="Search all Session evidence" value={query} /><select aria-label="Session lifecycle" onChange={(event) => setStateFilter(event.target.value)} value={stateFilter}>{["ALL", "ACTIVE", "COMPLETED", "EXPIRED", "ABANDONED", "CANCELLED"].map((item) => <option key={item}>{item}</option>)}</select><input aria-label="Customer filter" onChange={(event) => setCustomer(event.target.value)} placeholder="Customer ID" value={customer} /><input aria-label="Photoshoot filter" onChange={(event) => setPhotoshoot(event.target.value)} placeholder="Photoshoot reference" value={photoshoot} /><input aria-label="Progression filter" onChange={(event) => setProgression(event.target.value.toUpperCase())} placeholder="Progression" value={progression} /><label>Inactive before<input aria-label="Activity filter" type="date" onChange={(event) => setActivity(event.target.value)} value={activity} /></label><label>Expires on<input aria-label="Expiration filter" type="date" onChange={(event) => setExpiration(event.target.value)} value={expiration} /></label><input aria-label="Outcome filter" onChange={(event) => setOutcome(event.target.value)} placeholder="Outcome" value={outcome} /></div>{!selectedSession && <div className="commercial-admin__table">{visible.map((item) => <button className="commercial-admin__row" key={item.salesSessionId} onClick={() => navigate("sales", { session: item.salesSessionId })}><span><small>Sales Session</small><strong>{item.salesSessionId}</strong></span><span><small>Customer</small><strong>Fanvue #{item.fanvueUserId}</strong></span><span><small>Lifecycle</small><strong>{labels(item.state)} · {labels(item.progressionStage)}</strong></span><span><small>Activity</small><strong>{when(item.lastActivityAt)}</strong></span></button>)}</div>}{selected && <><button className="commercial-admin__back" onClick={() => navigate("sales")}>← Session queues</button>{notice && <OperatorState kind={notice.kind}>{notice.text}</OperatorState>}<div className="commercial-admin__split"><RecordCard authority="Sales Session" title={selected.salesSessionId} id={selected.salesSessionId} value={{ ...selected, ...detail }} /><section className="commercial-admin__card"><small>Canonical lifecycle commands</small><h3>Current state: {labels(selected.state)}</h3>{selected.state === "ACTIVE" ? <div className="commercial-admin__inline"><button onClick={() => void act("advance", { state: "ACTIVE", progressionStage: "PRESENTATION" })}>Advance</button><button onClick={() => void act("progression", { progressionStage: "PRESENTATION" })}>Set Progression</button><button onClick={() => void act("complete", { withPurchase: false })}>Complete</button><button onClick={() => void act("expire")}>Expire</button><button onClick={() => void act("abandon")}>Abandon</button><button onClick={() => void act("cancel")}>Cancel</button></div> : <OperatorState kind="unsupported">No lifecycle command is supported from this terminal state.</OperatorState>}<Relation label="Purchase Intents" values={intents.map((item) => [item.purchaseIntentId, () => navigate("sales", { session: selected.salesSessionId, intent: item.purchaseIntentId })])} /></section></div></>}</div>;
}

function Delivery({ data, refresh }: { data: AuthorityData; refresh: () => Promise<void> }) { const [notice, setNotice] = useState<{ kind: "stale" | "unauthorized" | "unsupported" | "failed"; text: string } | null>(null); const act = async (item: Publication, action: "retry" | "reconcile") => { if (!confirm(`${labels(action)} Publication ${item.publicationId}?`)) return; try { await command(`/api/v1/commercial-publications/${item.publicationId}/${action}`, {}); await refresh(); setNotice(null); } catch (reason) { setNotice(classifyCommandError(reason)); } }; return <div className="commercial-admin__area"><Heading title="Delivery and publication" description="Publication → Fanvue execution → programmatic Media Link → fulfillment → Telegram transport." />{notice && <OperatorState kind={notice.kind}>{notice.text}</OperatorState>}<div className="commercial-admin__grid">{data.publications.map((item) => { const metadata = item.publicationMetadata as Record<string, unknown>; const fulfillment = data.fulfillments.find((value) => value.publicationId === item.publicationId || value.offeringId === item.commercialOfferingId); return <article className="commercial-admin__card" key={item.publicationId}><small>Publication authority · {item.provider}</small><h3>{item.publicationId}</h3><Status good={item.status === "LIVE" && Boolean(fulfillment?.fulfillable)}>{labels(item.status)}</Status><Definition values={{ Offering: item.commercialOfferingId, "Provider resource": labels(item.providerResourceStatus), "Last reconciled": when(item.lastReconciledAt), "Retry count": String(item.retryCount), "Fulfillment": fulfillment?.fulfillable ? "Eligible" : `Blocked: ${fulfillment?.ineligibilityReason || "evidence unavailable"}`, "Delivery URL": fulfillment?.deliveryUrl || "Unavailable", "Telegram delivery": fulfillment?.eligibleForTelegramWall ? "Eligible" : "Not eligible or unsupported", "Media Link": String((metadata.media_link as Record<string, unknown> | undefined)?.uuid || item.externalProductId || "Not retrieved") }} /><StructuredFields title="Execution and upload checkpoints" value={metadata} /><div className="commercial-admin__inline"><button onClick={() => void act(item, "reconcile")}>Reconcile</button>{["FAILED", "PUBLISHING"].includes(item.status) && <button onClick={() => void act(item, "retry")}>{item.status === "PUBLISHING" ? "Resume" : "Retry"}</button>}</div></article>; })}</div><p className="commercial-admin__policy"><CheckCircle2 size={15} />Media Links are display-only and remain programmatically retrieved by Publication infrastructure.</p></div>; }

function Diagnostics({ data, exceptions, navigate }: { data: AuthorityData; exceptions: ExceptionItem[]; navigate: (area: AdminArea, values?: Record<string, string>) => void }) { return <div className="commercial-admin__area"><Heading title="Cross-domain diagnostics" description="Authority, provenance, confidence, insufficiency, conflict, and timestamps remain explicit." /><ExceptionList items={exceptions} navigate={navigate} /><div className="commercial-admin__grid"><DiagnosticCard authority="Commercial Roles" values={data.assetAuthorities.flatMap((item) => item.roles)} /><DiagnosticCard authority="Asset Lineage" values={data.assetAuthorities.map((item) => item.lineage).filter(Boolean)} /><DiagnosticCard authority="Ownership Intelligence" values={data.customers.map((item) => ({ customerId: item.customerId, destination: "Customer journey" }))} /><DiagnosticCard authority="Purchase Intents" values={data.intents} /><DiagnosticCard authority="Commercial Intelligence" values={data.decisions} /><DiagnosticCard authority="Offering and Fulfillment" values={data.fulfillments} /></div></div>; }

function buildExceptions(data: AuthorityData): ExceptionItem[] { const values: ExceptionItem[] = []; const add = (item: ExceptionItem) => values.push(item);
  data.assetAuthorities.forEach((item) => { const approved = item.roles.some((role) => role.state === "APPROVED"); if (!approved) add(exceptionFor(String(item.assetId), "Commercial Roles", "Missing effective role", "High", "No approved effective Commercial Role exists.", "MISSING", null, "catalog", { asset: String(item.assetId) })); item.roles.filter((role) => role.state === "SUGGESTED").forEach((role) => add(exceptionFor(String(item.assetId), "Commercial Roles", "Pending approval", role.suggestionConfidence != null && role.suggestionConfidence >= .8 ? "High" : "Medium", role.rationale || "A canonical suggestion awaits review.", role.state, role.updatedAt, "catalog", { asset: String(item.assetId) }))); const lineage = item.lineage; if (lineage?.ambiguous || !lineage?.complete || lineage?.integrity_status !== "VALID") add(exceptionFor(String(item.assetId), "Asset Lineage", lineage?.ambiguous ? "Ambiguity" : "Integrity", "High", lineage?.completeness_issues.join(", ") || "Canonical Lineage diagnostics require attention.", lineage?.integrity_status || "UNKNOWN", null, "catalog", { asset: String(item.assetId) })); });
  data.assets.forEach((item) => { if (item.blocked || item.waiting_for_media_link) add(exceptionFor(String(item.asset_id), "Asset commerce", item.waiting_for_media_link ? "Media Link retrieval" : "Readiness blocker", "High", ((item.block_reasons as string[]) || []).join(", ") || "Canonical commerce readiness is blocked.", String(item.commerceStatus), null, "catalog", { asset: String(item.asset_id) })); });
  data.customers.forEach((item) => { const text = JSON.stringify(item).toUpperCase(); if (text.includes("INSUFFICIENT") || text.includes("CONFLICT")) add(exceptionFor(String(item.customerId), "Ownership Intelligence", text.includes("CONFLICT") ? "Ownership conflict" : "Ownership insufficiency", "High", "Canonical Ownership Intelligence reports unresolved evidence.", text.includes("CONFLICT") ? "CONFLICTING" : "INSUFFICIENT", String(item.lastActivityAt || ""), "customers", { customer: String(item.customerId) })); });
  data.sessions.forEach((item) => { const stale = item.state === "ACTIVE" && item.lastActivityAt && Date.now() - new Date(item.lastActivityAt).getTime() > 24 * 60 * 60 * 1000; if (stale || ["ABANDONED", "EXPIRED"].includes(item.state)) add(exceptionFor(item.salesSessionId, "Sales Session", stale ? "Stalled Session" : "Terminal review", stale ? "High" : "Medium", stale ? "No activity has been recorded for more than 24 hours." : `Session ended as ${labels(item.state)}.`, item.state, item.lastActivityAt, "sales", { session: item.salesSessionId })); });
  data.intents.filter((item) => ["UNKNOWN", "EXPIRED", "ABANDONED"].includes(item.status) || item.attributionResult === "UNKNOWN").forEach((item) => add(exceptionFor(item.purchaseIntentId, "Purchase Intent", item.attributionResult === "UNKNOWN" ? "Attribution ambiguity" : "Lifecycle failure", "High", item.attributionReason || `Purchase Intent is ${labels(item.status)}.`, item.status, item.updatedAt, "sales", { intent: item.purchaseIntentId })));
  data.offerings.forEach((item) => { const fulfillment = data.fulfillments.find((value) => value.offeringId === item.offeringId); if (!fulfillment?.fulfillable) add(exceptionFor(String(item.offeringId), "Commercial Offering", "Readiness blocker", "High", fulfillment?.ineligibilityReason || "Fulfillment evidence is unavailable.", String(item.status), String(item.updatedAt || item.createdAt || ""), "delivery")); });
  data.products.forEach((item) => { const eligibility = item.recommendationEligibility as { eligible?: boolean; reasons?: string[] } | undefined; if (eligibility && !eligibility.eligible) add(exceptionFor(String(item.productId), "Product", "Lifecycle conflict", "Medium", eligibility.reasons?.join(", ") || "Product is not recommendation eligible.", String(item.productStatus || item.lifecycleStage), String(item.updatedAt || ""), "catalog")); });
  data.publications.forEach((item) => { if (item.status === "FAILED") add(exceptionFor(item.publicationId, "Publication", "Execution failure", "Critical", item.lastError || "Publication failed.", item.status, item.updatedAt, "delivery")); if (item.status === "LIVE" && item.providerResourceStatus !== "PRESENT") add(exceptionFor(item.publicationId, "Fanvue reconciliation", "Provider drift", "High", "Live Publication is not verified at Fanvue.", item.providerResourceStatus, item.lastReconciledAt, "delivery")); });
  const learning = data.learning as { suppressionReasons?: Record<string, number>; rejectionReasons?: Record<string, number>; deliveryFailures?: Record<string, unknown>[] }; Object.entries(learning.suppressionReasons || {}).filter(([, count]) => count > 1).forEach(([reason, count]) => add(exceptionFor(reason, "Commercial Intelligence", "Repeated suppression", "Medium", `${count} recorded suppressions.`, "RECORDED", null, "diagnostics"))); Object.entries(learning.rejectionReasons || {}).filter(([, count]) => count > 1).forEach(([reason, count]) => add(exceptionFor(reason, "Commercial Intelligence", "Repeated no-sale cause", "Medium", `${count} recorded rejections.`, "RECORDED", null, "diagnostics"))); (learning.deliveryFailures || []).forEach((item, index) => add(exceptionFor(String(item.id || index), "Telegram / Fulfillment", "Delivery failure", "High", String(item.reason || "Canonical delivery failure."), "FAILED", String(item.timestamp || ""), "delivery")));
  return values.sort((a, b) => ["Critical", "High", "Medium", "Information"].indexOf(a.severity) - ["Critical", "High", "Medium", "Information"].indexOf(b.severity)); }

function exceptionFor(id: string, authority: string, type: string, severity: ExceptionItem["severity"], explanation: string, state: string, timestamp: string | null | undefined, area: AdminArea, params: Record<string, string> = {}): ExceptionItem { const query = new URLSearchParams({ area, ...params }); return { id, authority, type, severity, explanation, state, timestamp, destination: `/commercial-administration?${query}` }; }
function classifyCommandError(reason: unknown) { const error = reason instanceof AuthorityError ? reason : new AuthorityError("The canonical command failed.", 500); if (error.status === 401 || error.status === 403) return { kind: "unauthorized" as const, text: error.message }; if (error.status === 409) return { kind: "stale" as const, text: `Stale or unsupported transition: ${error.message}` }; if (error.status === 404) return { kind: "unsupported" as const, text: error.message }; return { kind: "failed" as const, text: error.message }; }
function ErrorState({ error }: { error: AuthorityError }) { return <OperatorState kind={error.status === 401 || error.status === 403 ? "unauthorized" : error.status >= 500 ? "dependency" : "failed"}>{error.message}</OperatorState>; }
function OperatorState({ kind, children }: { kind: "loading" | "empty" | "dependency" | "unauthorized" | "stale" | "conflicting" | "insufficient" | "unsupported" | "failed"; children: React.ReactNode }) { return <div className={`commercial-admin__state commercial-admin__state--${kind}`} role={["failed", "unauthorized", "dependency"].includes(kind) ? "alert" : "status"}><strong>{labels(kind)}</strong><span>{children}</span></div>; }
function Breadcrumb({ values }: { values: string[] }) { return <nav aria-label="Breadcrumb" className="commercial-admin__breadcrumb">{values.map((value, index) => <span key={`${value}-${index}`}>{index > 0 && "›"}{value}</span>)}</nav>; }
function Metric({ label, value }: { label: string; value: number }) { return <article><small>{label}</small><strong>{value}</strong></article>; }
function Heading({ title, description }: { title: string; description: string }) { return <header className="commercial-admin__heading"><h2>{title}</h2><p>{description}</p></header>; }
function Status({ children, good }: { children: React.ReactNode; good: boolean }) { return <span className={`commercial-admin__status ${good ? "is-good" : "needs-attention"}`}>{children}</span>; }
function Definition({ values }: { values: Record<string, string> }) { return <dl className="commercial-admin__definition">{Object.entries(values).map(([key, value]) => <div key={key}><dt>{key}</dt><dd>{value}</dd></div>)}</dl>; }
function StructuredFields({ title, value }: { title: string; value: unknown }) { const entries = value && typeof value === "object" ? Object.entries(value as Record<string, unknown>) : []; return <details className="commercial-admin__structured"><summary>{title}</summary>{entries.length ? <dl className="commercial-admin__definition">{entries.map(([key, item]) => <div key={key}><dt>{labels(key)}</dt><dd>{typeof item === "object" ? JSON.stringify(item) : String(item ?? "Unknown")}</dd></div>)}</dl> : <p>No canonical evidence was supplied.</p>}</details>; }
function RecordCard({ authority, title, id, value }: { authority: string; title: string; id: string | null; value: unknown }) { return <section className="commercial-admin__card"><small>{authority} authority</small><h3>{title}</h3><code>{id || "Unknown canonical ID"}</code><StructuredFields title="Structured authoritative evidence" value={value} /></section>; }
function DiagnosticCard({ authority, values }: { authority: string; values: unknown[] }) { return <section className="commercial-admin__card"><small>{authority} authority</small><h3>{values.length} diagnostic records</h3><StructuredFields title="Evidence and provenance" value={values} /></section>; }
function Relation({ label, values }: { label: string; values: [string, () => void][] }) { return <div className="commercial-admin__relations"><strong>{label}</strong>{values.length ? values.map(([id, action]) => <button key={id} onClick={action}>{id}</button>) : <span>No canonical relationship supplied.</span>}</div>; }
function CatalogGroup({ title, items, idKey, onSelect, fulfillments = [] }: { title: string; items: Record<string, unknown>[]; idKey: string; onSelect?: (id: string) => void; fulfillments?: Fulfillment[] }) { return <section><Heading title={title} description={`${items.length} canonical records`} /><div className="commercial-admin__grid">{items.map((item) => { const id = String(item[idKey]); const fulfillment = fulfillments.find((value) => value.offeringId === id); const content = <><small>{title} authority</small><h3>{String(item.displayName || item.title || item.asset_name || id)}</h3><code>{id}</code><p>{labels(String(item.status || item.productStatus || item.commerceStatus))}{fulfillment ? ` · ${fulfillment.fulfillable ? "Fulfillable" : fulfillment.ineligibilityReason || "Blocked"}` : ""}</p></>; return onSelect ? <button className="commercial-admin__card commercial-admin__select-card" key={id} onClick={() => onSelect(id)}>{content}</button> : <article className="commercial-admin__card" key={id}>{content}</article>; })}</div>{!items.length && <OperatorState kind="empty">No matching {title.toLowerCase()}.</OperatorState>}</section>; }
function ExceptionList({ items, navigate }: { items: ExceptionItem[]; navigate: (area: AdminArea, values?: Record<string, string>) => void }) { return <div className="commercial-admin__exceptions">{items.map((item) => <article key={`${item.authority}-${item.id}-${item.type}`}><span className={`severity severity--${item.severity.toLowerCase()}`}>{item.severity}</span><div><small>{item.authority} · {item.type}</small><strong>{item.id}</strong><p>{item.explanation}</p><span>{labels(item.state)} · {when(item.timestamp)}</span></div><button onClick={() => { const url = new URL(item.destination, window.location.origin); navigate((url.searchParams.get("area") || "overview") as AdminArea, Object.fromEntries([...url.searchParams.entries()].filter(([key]) => key !== "area"))); }}>Inspect <ExternalLink size={13} /></button></article>)}</div>; }
